<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch,computed,nextTick} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Sparkles,X,ArrowUpRight} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
const store=useLocal(),route=useRoute(),router=useRouter(),enabled=ref(true),hidden=ref(false),menu=ref(false),position=ref({x:0,y:0}),count=ref(0),dragging=ref(false)
const hasSpace=ref(true)
const visible=computed(()=>enabled.value&&!hidden.value&&hasSpace.value&&route.path!=='/local/agent'&&route.path!=='/local/insights')
let disposed=false,moved=false,start:{clientX:number;clientY:number;x:number;y:number}|null=null,poll:ReturnType<typeof setInterval>|null=null,avoidance:ResizeObserver|null=null,domObserver:MutationObserver|null=null,layoutFrame=0
const bounds=()=>{const viewport=window.visualViewport;return {width:viewport?.width||innerWidth,height:viewport?.height||innerHeight}}
const protectedZones='.shell-mobile-nav,.shell-mobile-header,.character-grid .final-grid-actions,.character-search input,.character-tools summary,.character-filter-menu summary,.card-more>div,.discover-genres button,.discover-search input,.discover-feature button,.discover-page .final-book button,.companion-card,.companion-search input,.companion-profile-hero,.companion-workspace .final-memory,.companion-workspace .records-panel,.companion-workspace .world-panel,.settings-advanced summary,.library-view-options summary,.library-resume,.appearance-page button,.appearance-page input,.appearance-page select,.appearance-import button,.appearance-import textarea,.settings-search input,.settings-link,.settings-lock button,.final-vn-dialogue,.final-vn-show,.final-chat-composer,.final-agent-composer,.library-book-actions,.library-selection-bar,.play-toolbar a,.play-toolbar button,.play-actions button,.play-controls,.play-drawer,.play-recovery button,.play-template,.play-launch button,.play-import,.task-filters input,.task-filters select,.task-row,.task-detail-actions a,.task-detail-actions button,.task-pagination button,.final-page-heading,.final-card-form input,.final-card-form select,.final-card-form textarea,.final-card-form button,.original-story-form input,.original-story-form textarea,.original-story-form button'
function clamp(){
 const {width,height}=bounds(),maxX=Math.max(12,width-60),maxY=Math.max(12,height-(route.meta.immersive?220:104)-48)
 const preferred={x:Math.max(12,Math.min(position.value.x,maxX)),y:Math.max(12,Math.min(position.value.y,maxY))}
 const zones=[...document.querySelectorAll('.shell-sidebar,.shell-content button,.shell-content input,.shell-content select,.shell-content textarea,.shell-content summary,.shell-content a,'+protectedZones)].filter(el=>{if(typeof el.checkVisibility==='function')return el.checkVisibility({visibilityProperty:true,contentVisibilityAuto:true});const style=getComputedStyle(el);if(style.visibility==='hidden'||style.display==='none')return false;for(let parent=el.parentElement;parent;parent=parent.parentElement)if(parent instanceof HTMLDetailsElement&&!parent.open&&!parent.querySelector('summary')?.contains(el))return false;return !!el.getClientRects().length}).map(el=>el.getBoundingClientRect()).filter(r=>r.width&&r.height&&r.bottom>0&&r.top<height&&r.right>0&&r.left<width)
 const fits=(p:{x:number;y:number})=>p.x>=12&&p.x<=maxX&&p.y>=12&&p.y<=maxY&&zones.every(r=>p.x+48<=r.left-8||p.x>=r.right+8||p.y+48<=r.top-8||p.y>=r.bottom+8)
 if(fits(preferred)){hasSpace.value=true;position.value=preferred;return}
 const candidates=[{x:12,y:12},{x:maxX,y:12},{x:12,y:maxY},{x:maxX,y:maxY}]
 for(const r of zones)candidates.push({x:preferred.x,y:r.top-56},{x:preferred.x,y:r.bottom+8},{x:r.left-56,y:preferred.y},{x:r.right+8,y:preferred.y})
 for(let y=12;y<=maxY;y+=56)for(let x=maxX;x>=12;x-=56)candidates.push({x,y})
 const nearest=candidates.filter(fits).sort((a,b)=>(a.x-preferred.x)**2+(a.y-preferred.y)**2-((b.x-preferred.x)**2+(b.y-preferred.y)**2))[0]
 hasSpace.value=!!nearest
 if(nearest)position.value=nearest
}
async function observeZones(){await nextTick();if(disposed)return;avoidance?.disconnect();avoidance=new ResizeObserver(clamp);for(const element of document.querySelectorAll(protectedZones))avoidance.observe(element);clamp()}
async function load(){const vault=store.vault;if(!vault)return;const row=await vault.read<{enabled:boolean;position?:{x:number;y:number}}>('settings:agent-ui');if(disposed||store.vault!==vault)return;enabled.value=row?.value.enabled!==false;if(row?.value.position)position.value=row.value.position;else position.value={x:innerWidth-76,y:innerHeight-300};clamp()}
async function save(){const vault=store.vault;if(!vault)return;const row=await vault.read('settings:agent-ui'),value={enabled:enabled.value,position:{...position.value}};await vault.commit(crypto.randomUUID(),'settings','settings:agent-ui',row?.revision||0,value);window.dispatchEvent(new Event('reader-agent-ui-changed'))}
function down(event:PointerEvent){if(event.button!==0)return;moved=false;start={clientX:event.clientX,clientY:event.clientY,...position.value};dragging.value=true;(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId)}
function move(event:PointerEvent){if(!start)return;if(Math.abs(event.clientX-start.clientX)+Math.abs(event.clientY-start.clientY)>5)moved=true;position.value={x:start.x+event.clientX-start.clientX,y:start.y+event.clientY-start.clientY};clamp()}
function up(){if(!start)return;start=null;dragging.value=false;if(moved)void save().catch(()=>{})}
function toggle(){if(moved){moved=false;return}menu.value=!menu.value}
function open(){const storyId=route.params.storyId,sessionId=route.params.sessionId;void router.push({path:'/local/agent',query:typeof storyId==='string'?{ref:storyId}:typeof sessionId==='string'?{ref:sessionId}:{}})}
async function disable(){enabled.value=false;menu.value=false;await save()}
async function refreshCount(){const vault=store.vault;if(!vault)return;const runs=await vault.list<{status:string}>('agentRun');if(!disposed&&store.vault===vault)count.value=runs.filter(run=>['planning','streaming','running','needs_approval'].includes(run.value.status)).length}
watch(()=>route.fullPath,()=>{menu.value=false;void observeZones()},{flush:'post'})
const update=()=>void load().catch(()=>{}),resize=()=>clamp()
onMounted(()=>{void load().then(observeZones).catch(()=>{});domObserver=new MutationObserver(()=>{if(!layoutFrame)layoutFrame=requestAnimationFrame(()=>{layoutFrame=0;void observeZones()})});const content=document.querySelector('.shell-content');if(content)domObserver.observe(content,{childList:true,subtree:true});void refreshCount().catch(()=>{});poll=setInterval(()=>void refreshCount().catch(()=>{}),3000);window.addEventListener('reader-agent-ui-changed',update);window.addEventListener('resize',resize);window.addEventListener('scroll',resize,{passive:true,capture:true});window.visualViewport?.addEventListener('resize',resize)})
onUnmounted(()=>{disposed=true;avoidance?.disconnect();domObserver?.disconnect();if(layoutFrame)cancelAnimationFrame(layoutFrame);if(poll)clearInterval(poll);window.removeEventListener('reader-agent-ui-changed',update);window.removeEventListener('resize',resize);window.removeEventListener('scroll',resize,true);window.visualViewport?.removeEventListener('resize',resize)})
</script>
<template><div v-if="visible" class="final-agent-dock" :style="{left:position.x+'px',top:position.y+'px'}"><button class="final-agent-orb" aria-label="打开创作助手菜单" :aria-expanded="menu" @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up" @click="toggle"><Sparkles :size="22"/><span v-if="count" class="final-agent-count">{{count}}</span></button><div v-if="menu&&!dragging" class="final-agent-dock-menu" :class="{'is-below':position.y<200,'is-left':position.x<190}"><button @click="open"><ArrowUpRight :size="16"/>创作助手</button><button @click="hidden=true"><X :size="16"/>暂时隐藏</button><button @click="disable">关闭悬浮入口</button></div></div></template>
<style scoped>
.final-agent-dock{position:fixed;z-index:24;max-width:48px}.final-agent-orb{width:48px;height:48px;padding:0!important;display:flex;align-items:center;justify-content:center;border-radius:50%!important;box-shadow:0 4px 20px #29241918;color:var(--accent)!important;touch-action:none!important;background:var(--canvas)!important}.final-agent-orb:hover{background:var(--wash)!important}.final-agent-count{position:absolute;right:-2px;top:-4px;width:20px;height:20px;font-size:11px;border-radius:50%;background:var(--accent);color:var(--on-accent);display:grid;place-items:center}.final-agent-dock-menu{position:absolute;right:0;bottom:56px;width:190px;padding:8px;border:1px solid var(--edge);border-radius:16px;box-shadow:0 8px 32px #29241915;background:var(--canvas);display:grid;gap:4px}.final-agent-dock-menu.is-below{bottom:auto;top:56px}.final-agent-dock-menu.is-left{right:auto;left:0}.final-agent-dock-menu button{display:flex;align-items:center;gap:8px;border:0!important;justify-content:flex-start}
</style>
